#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const files = [
  "supabase/migrations/20260910120000_b2b_exchange.sql",
  "supabase/migrations/20260911120000_b2b_exchange_subscriptions.sql",
];
const parts = files.map((rel) => ({
  name: path.basename(rel),
  sql: fs.readFileSync(path.join(root, rel), "utf8"),
}));
const outPath = path.join(root, "lib/exchange/embedded-migrations.ts");
const out =
  "/** Auto-generated by scripts/generate-exchange-embedded-sql.mjs — do not edit. */\n" +
  "export const EXCHANGE_MIGRATION_SQL: { name: string; sql: string }[] = " +
  JSON.stringify(parts, null, 2) +
  ";\n";
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, out);
console.log("wrote", outPath, "bytes=" + out.length);

const edgePath = path.join(root, "scripts/edge-apply-exchange-data.mjs");
fs.writeFileSync(
  edgePath,
  "export const MIGRATIONS = " + JSON.stringify(parts, null, 2) + ";\n"
);
console.log("wrote", edgePath);
